const LABELS = {"expandedPrinting": "Expanded · printing (Home)", "collapsedIdle": "Collapsed · idle (Home)", "collapsedFirstRun": "Collapsed · idle (first-run Home)", "sheetExpanded": "Component sheet · expanded printing (Figma-era drawing)", "sheetCollapsedIdle": "Component sheet · collapsed idle (Figma-era drawing)", "sheetCollapsedOffline": "Component sheet · collapsed offline (Figma-era drawing)"};
const CAPTIONS = {"expandedPrinting": "", "collapsedIdle": "", "collapsedFirstRun": "", "sheetExpanded": "", "sheetCollapsedIdle": "", "sheetCollapsedOffline": ""};
const BOARD = ["expandedPrinting", "collapsedIdle", "collapsedFirstRun", "sheetExpanded", "sheetCollapsedIdle", "sheetCollapsedOffline"];
const KEYS = ["design", "printer", "status", "specs", "material", "slots", "action", "progress", "progressLabel", "progressWidth", "swatch1", "swatch2", "swatch3", "swatch4", "swatchStyle", "boxStyle", "nameStyle", "dotStyle"];
const FRAME = 'width:1032px;box-sizing:border-box;display:flex;flex-wrap:wrap;align-items:flex-start;gap:var(--space-32) var(--space-24);padding:var(--space-32);background:var(--surface-canvas)';
const TILE = 'width:272px;display:flex;flex-direction:column;align-items:flex-start;gap:var(--space-8)';
const on = (v) => v === true || v === 'true';
function derive(o) {
  return {};
}
function view(o) { const v = { ...o, ...derive(o) }; v['is_' + o.design] = true; return v; }
class Component extends DCLogic {
  renderVals() {
    const p = this.props;
    const theme = p.theme ?? 'light';
    const variant = p.variant ?? 'all';
    if (variant === 'all') {
      return { theme, showFlows: true, frameStyle: FRAME, tiles: BOARD.map((n) => ({ ...view({ ...PRESETS[n] }), label: LABELS[n], caption: CAPTIONS[n], tileStyle: TILE })) };
    }
    const o = { ...(PRESETS[variant] || PRESETS[BOARD[0]]) };
    for (const k of KEYS) if (p[k] !== undefined) o[k] = p[k];
    return { theme, showFlows: false, frameStyle: 'display:contents', tiles: [{ ...view(o), label: '', caption: '', tileStyle: 'display:contents' }] };
  }
}
</script>
</body>
</html>

