import http.server, threading, queue, json, sys, os, time
cmds=queue.Queue(); results=queue.Queue()
ROOT=os.path.join(os.path.dirname(os.path.abspath(__file__)),'www')
class H(http.server.SimpleHTTPRequestHandler):
    def __init__(s,*a,**k): super().__init__(*a,directory=ROOT,**k)
    def end_headers(s):
        s.send_header('Cache-Control','no-store'); s.send_header('Access-Control-Allow-Origin','*'); super().end_headers()
    def log_message(s,*a): pass
    def do_GET(s):
        if s.path=='/cmd':
            try: c=cmds.get(timeout=20)
            except queue.Empty: c=''
            b=c.encode(); s.send_response(200); s.send_header('Content-Length',str(len(b))); s.end_headers(); s.wfile.write(b); return
        return super().do_GET()
    def do_POST(s):
        n=int(s.headers.get('Content-Length',0)); body=s.rfile.read(n).decode()
        if s.path=='/log':
            with open('bridge.log','a') as f: f.write(time.strftime('%H:%M:%S ')+body+'\n')
        elif s.path=='/result': results.put(body)
        elif s.path=='/run':
            cmds.put(body)
            try: r=results.get(timeout=30)
            except queue.Empty: r='TIMEOUT (page did not pick up the command)'
            b=r.encode(); s.send_response(200); s.send_header('Content-Length',str(len(b))); s.end_headers(); s.wfile.write(b); return
        s.send_response(204); s.end_headers()
    do_OPTIONS=lambda s:(s.send_response(204),s.send_header('Access-Control-Allow-Methods','GET,POST'),s.send_header('Access-Control-Allow-Headers','*'),s.end_headers())
http.server.ThreadingHTTPServer(('127.0.0.1',8799),H).serve_forever()
EOF
