import functools, http.server, socketserver, subprocess, sys, tempfile, threading, re
from pathlib import Path
work = Path('work-printer-status'); proj = work/'project'
probe = '''<script>setTimeout(()=>{const find=(root)=>{let c=root.querySelector('[data-n=printer-cabinet]');if(c)return c;for(const e of root.querySelectorAll('*'))if(e.shadowRoot){const r=find(e.shadowRoot);if(r)return r}};const c=find(document);const top=c.getBoundingClientRect().top;const out=[...c.children].map(e=>{const r=e.getBoundingClientRect();return Math.round(r.top-top)+'-'+Math.round(r.bottom-top)+':'+(e.innerText||'').split('\\n')[0].slice(0,24)});document.title='M|'+c.clientHeight+'|'+out.join('|')},3000)</script>'''
class H(http.server.SimpleHTTPRequestHandler):
    def log_message(self,*a): pass
    def translate_path(self, path):
        p = path.split('?')[0]
        if p.endswith('/support.js'): return str(work/'runtime'/'dc-runtime.js')
        return super().translate_path(path)
    def do_GET(self):
        if self.path.split('?')[0].endswith('.dc.html'):
            s=(proj/self.path.split('?')[0].lstrip('/')).read_text().replace('</body>',probe+'</body>').encode()
            self.send_response(200);self.send_header('Content-Type','text/html');self.send_header('Content-Length',str(len(s)));self.end_headers();self.wfile.write(s);return
        return super().do_GET()
srv=socketserver.ThreadingTCPServer(('127.0.0.1',0),functools.partial(H,directory=str(proj)));srv.daemon_threads=True
threading.Thread(target=srv.serve_forever,daemon=True).start()
for n in sys.argv[1:]:
    r=subprocess.run(['/Applications/Google Chrome.app/Contents/MacOS/Google Chrome','--headless=new','--disable-gpu',f'--user-data-dir={tempfile.mkdtemp()}','--window-size=1280,800','--virtual-time-budget=8000','--dump-dom',f'http://127.0.0.1:{srv.server_address[1]}/{n}'],capture_output=True,text=True,timeout=90)
    m=re.search(r'<title>(M\|[^<]*)</title>',r.stdout); print(n); print('  ', m.group(1).replace('|','\n   ') if m else 'no result')
EOF
