content.content:
/* Every color, radius, and type metric below resolves through a custom
   property that tokens.ts writes from resources/jusprin/ui/design-tokens.json:
   --<group>-<name> for colors, --radius-<name> for radii, --font-<role> for
   the `font` shorthand of each type role, and the --project-card-*,
   --printer-card-* and --status-dot-* card geometry. Padding, margin, and gap
   stay literal but must sit on the spacing scale. styles.test.ts fails the
   build on any literal outside those rules. */

/* The product font ships with OrcaSlicer, but it is registered as a private
   font of the native process and the web view renders in a separate process
   that cannot see it. The Latin subset shared with the Agent page is embedded
   so Home uses the same face as the native shell; CJK text falls through to
   the system font. */
@font-face {
  font-family: 'HarmonyOS Sans SC';
  font-weight: 400;
  font-style: normal;
  src: url('../../WebShared/fonts/HarmonyOS_Sans_SC_Regular_latin.woff') format('woff');
}
@font-face {
  font-family: 'HarmonyOS Sans SC';
  font-weight: 700;
  font-style: normal;
  src: url('../../WebShared/fonts/HarmonyOS_Sans_SC_Bold_latin.woff') format('woff');
}

* {
  box-sizing: border-box;
}

  text-overflow: ellipsis;
}

.project-card.printing .project-status {
  color: var(--status-success);
}

.status-dot {
  flex: 0 0 auto;
  width: var(--status-dot-size);
  height: var(--status-dot-size);
  border-radius: var(--radius-full);
  background: var(--text-secondary);
}

.status-dot.printing {
  background: var(--status-success);
}

/* A printer card's dot is its connection: reachable, or known and silent. A
   printer with nothing verified draws no dot at all. */
.status-dot.online,
.status-dot.connected {
  background: var(--status-success);
}

.status-dot.offline {
  background: var(--status-warning);
}

/* Read by a screen reader, not drawn. */
.visually-hidden {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip-path: inset(50%);
  white-space: nowrap;
}

/* Printer rail: a fixed column, full height beside the gallery. */
.printer-column {
  flex: 0 0 var(--printer-card-column-width);
  display: flex;
  flex-direction: column;
  gap: 16px;
  overflow-y: auto;
  padding: 24px;
  border-left: 1px solid var(--border-subtle);
}

.printer-card {
  display: flex;
  flex-direction: column;
  gap: 4px;
  padding: var(--printer-card-padding);
  background: var(--surface-raised);
  border: 1px solid var(--border-subtle);
  border-radius: var(--printer-card-radius);
  box-shadow: var(--elevation-subtle);
}

/* An idle printer on one line. With the swatch at its token size, the 8 DIP
   padding gives the board's 42 DIP chip without a height of its own. */
.printer-chip {
  display: flex;
  align-items: center;
  gap: 8px;
  width: 100%;
  padding: 8px 12px;
  font: var(--font-body-small);
  color: var(--text-primary);
  text-align: left;
  background: var(--surface-raised);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-medium);
  cursor: pointer;
}

.printer-chip:hover {
  background: var(--surface-raised-hover);
}

.printer-chip-name {
  min-width: 0;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.printer-chip-status {
  flex: 0 0 auto;
  font: var(--font-label);
  color: var(--text-secondary);
  white-space: nowrap;
}

.printer-chip-loaded {
  flex: 0 0 auto;
  display: flex;
  align-items: center;
  gap: 4px;
  margin-left: auto;
  font: var(--font-label);
  color: var(--text-secondary);
  white-space: nowrap;
}

.printer-head {
  display: flex;
