tools.description:
Open the Browser pane: pass `url` to open a browser tab at a URL (no dev server needed — use this for external sites, staging, docs, or your deployed app), OR pass `name` to start a dev server from .claude/launch.json.

Start a dev server by name from .claude/launch.json. If .claude/launch.json doesn't exist, create it first with this format:
{
  "version": "0.0.1",
  "configurations": [
    {
      "name": "<unique-name>",
      "runtimeExecutable": "<command>",
      "runtimeArgs": ["<args>"],
      "port": <port>
    }
  ]
}
Set "runtimeExecutable" to the command (e.g. "npm"), "runtimeArgs" to the arguments (e.g. ["run", "dev"]), and "port" to the server port. An optional "url" (http/https) opens the preview there instead of http://localhost:<port>. A localhost "url" must be just the server's origin — no path or query, matching the entry's port — for example "https://localhost:8443" or "http://app.localhost:3000"; to show a specific page, navigate after the preview opens. Non-localhost URLs may carry paths and are subject to the user's permission and the organization's browsing policy. A configuration with "url" and no command attaches to an already-running server. Only include servers you actually need to preview. Reuses the server if already running. ALWAYS use this instead of Bash for running servers. If the deliverable is already published as an Artifact, update the Artifact instead of starting a server to show it.

file.content:
// The printer card: one status, then each field only when the host sent it,
// so the card grows and shrinks with what the printer reports.

import { describe, expect, it, vi } from 'vitest';
import { act, fireEvent, render, screen } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import type { PrinterInfo } from '../bridge/protocol';
import { lastConnected, PrinterCard, statusDetail, timeLeft } from './PrinterCard';

function printer(overrides: Partial<PrinterInfo> = {}): PrinterInfo {
  return {
    id: 'named:Bench',
    name: 'Bench',
    kind: 'named',
    canOpenSettings: true,
    canRename: true,
    canRemove: true,
    status: 'ready',
    modelText: 'X1 Carbon · 0.4 mm',
    spools: [],
    action: 'none',
    ...overrides,
  };
}

const NOW = new Date('2026-11-05T15:00:00Z');

function card(info: PrinterInfo, onLaunchMonitor = vi.fn(), onConnect = vi.fn(), onHistory = vi.fn()) {
  const actions = { onConnect, onOpenSettings: vi.fn(), onRename: vi.fn(), onRemove: vi.fn() };
  render(
    <PrinterCard
      printer={info}
      otherNames={[]}
      actions={actions}
      onLaunchMonitor={onLaunchMonitor}
      onHistory={onHistory}
      now={NOW}
    />,
  );
  return document.querySelector('.printer-card') as HTMLElement;
}

// The card's parts in order, by class, under the card itself.
function parts(element: HTMLElement): string[] {
  return [...element.children].map((child) => child.className.split(' ')[0]);
}

describe('the status line', () => {
  it.each([
    ['printing', 'Printing', 'printing'],
    ['ready', 'Ready', 'ready'],
    ['paused', 'Paused', 'paused'],
    ['attention', 'Needs attention', 'attention'],
    ['connected', 'Connected', 'connected'],
  ] as const)('says %s with its own dot', (status, word, dot) => {
    const element = card(printer({ status }));
    expect(element.querySelector('.printer-status-word')).toHaveTextContent(word);
    expect(element.querySelector('.printer-status .status-dot')).toHaveClass(dot);
  });

  it.each([
    ['not_connected', 'Not connected'],
    ['connecting', 'Connecting…'],
  ] as const)('says %s in words with no dot', (status, word) => {
    const element = card(printer({ status }));
    expect(element.querySelector('.printer-status-word')).toHaveTextContent(word);
    expect(element.querySelector('.printer-status .status-dot')).toBeNull();
  });

  it('follows the word with how far a job is, or how the last one ended', () => {
    expect(statusDetail(printer({ status: 'printing', progressPercent: 43, secondsLeft: 8040 }))).toBe('43% · 2h 14m left');
    expect(statusDetail(printer({ status: 'printing', progressPercent: 61 }))).toBe('61%');
    expect(statusDetail(printer({ status: 'printing' }))).toBeUndefined();
    expect(statusDetail(printer({ status: 'paused', progressPercent: 27 }))).toBe('at 27%');
    expect(statusDetail(printer({ status: 'ready', lastPrint: 'failed' }))).toBe('last print failed');
    expect(statusDetail(printer({ status: 'ready' }))).toBeUndefined();
    // A printer that is not connected has no job to report on.
    expect(statusDetail(printer({ status: 'not_connected', progressPercent: 27 }))).toBeUndefined();
  });

  it('words the time left', () => {
    expect(timeLeft(8040)).toBe('2h 14m left');
    expect(timeLeft(840)).toBe('14m left');
    expect(timeLeft(20)).toBe('1m left');
  });
});

describe('the fields', () => {
  it('shows only the name, the status and the facts when that is all there is', () => {
    const element = card(printer());
    expect(parts(element)).toEqual(['printer-head', 'printer-status', 'printer-facts']);
  });

  it('keeps the boards order when every field has a value', () => {
    const element = card(
      printer({
        status: 'paused',
        job: 'Phone stand',
        progressPercent: 27,
        message: 'AMS A Slot 1 filament has run out. Please insert a new filament.',
        camera: { streamUrl: 'http://127.0.0.1:7140/api/stream.mjpeg?src=klipper' },
        connectionLabel: 'Cloud',
        spools: [{ material: 'PLA', colour: '#262626' }],
        history: { gcodes: 9, exports: 0, sends: 9, prints: 9, printingNow: 1 },
        action: 'monitor',
      }),
    );
    expect(parts(element)).toEqual([
      'printer-camera',
      'printer-head',
      'printer-status',
      'printer-job',
      'printer-progress',
      'printer-message',
      'printer-facts',
      'printer-spools',
      'project-history',
      'button-secondary',
    ]);
  });

  it('shows the job and its bar while a job runs, and not on a ready printer', () => {
    card(printer({ status: 'printing', job: 'Vent grille', progressPercent: 43 }));
    expect(screen.getByText('Vent grille')).toBeInTheDocument();
    expect(screen.getByRole('progressbar')).toHaveAttribute('aria-valuenow', '43');
    document.body.innerHTML = '';
    card(printer({ status: 'ready', job: 'Vent grille', progressPercent: 100 }));
    expect(screen.queryByText('Vent grille')).toBeNull();
    expect(screen.queryByRole('progressbar')).toBeNull();
  });

  it('joins how it is reached, its address, model and nozzle on one line', () => {
    const element = card(
      printer({ connectionLabel: 'Klipper', address: 'voron.local', modelText: 'Voron 2.4 · 0.4 mm' }),
    );
    expect(element.querySelector('.printer-facts')).toHaveTextContent('Klipper · voron.local · Voron 2.4 · 0.4 mm');
  });

  it('says when a printer that is not connected was last heard from, and nothing when unknown', () => {
    card(
      printer({
        status: 'not_connected',
        message: "Klipper stopped: Lost communication with MCU 'mcu'",
        lastConnectedAt: '2026-11-05T12:00:00Z',
      }),
    );
    expect(screen.getByText("Klipper stopped: Lost communication with MCU 'mcu'")).toBeInTheDocument();
    expect(screen.getByText('Last connected 3h ago')).toBeInTheDocument();
    document.body.innerHTML = '';
    card(printer({ status: 'not_connected', message: 'No network connection is set up.' }));
    expect(screen.queryByText(/Last connected/)).toBeNull();
  });

  it('words how long ago', () => {
    expect(lastConnected('2026-11-05T14:59:40Z', NOW)).toBe('Last connected just now');
    expect(lastConnected('2026-11-05T14:40:00Z', NOW)).toBe('Last connected 20 min ago');
    expect(lastConnected('2026-11-04T15:00:00Z', NOW)).toBe('Last connected 1 day ago');
    expect(lastConnected('2026-11-03T14:00:00Z', NOW)).toBe('Last connected 2 days ago');
    expect(lastConnected('not a date', NOW)).toBeUndefined();
  });

  it('names the materials once and draws a swatch per coloured spool', () => {
    const element = card(
      printer({
        spools: [
          { material: 'PLA', colour: '#9A9A9A' },
          { material: 'PETG', colour: '#C8202D' },
          { material: 'PLA', colour: '#FFFFFF' },
          { material: 'PLA' },
        ],
      }),
    );
    const loaded = element.querySelector('.printer-spools')!;
    expect(loaded).toHaveTextContent('PLA, PETG');
    expect(loaded.querySelectorAll('.spool-swatch')).toHaveLength(3);
  });
});

describe('the camera', () => {
  it('shows a stream on any status, as long as it answers', () => {
    const element = card(printer({ status: 'ready', camera: { streamUrl: 'http://cam/stream' } }));
    const image = screen.getByRole('img', { name: 'Camera view of Bench' });
    expect(image).toHaveAttribute('src', 'http://cam/stream');
    fireEvent.error(image);
    expect(element.querySelector('.printer-camera')).toBeNull();
  });

  it('asks a camera with only a picture for the next one every two seconds', () => {
    vi.useFakeTimers();
    try {
      card(printer({ status: 'printing', camera: { snapshotUrl: 'http://cam/frame.jpeg?src=klipper' } }));
      const image = screen.getByRole('img', { name: 'Camera view of Bench' });
      expect(image).toHaveAttribute('src', 'http://cam/frame.jpeg?src=klipper&t=0');
      act(() => {
        vi.advanceTimersByTime(2000);
      });
      expect(image).toHaveAttribute('src', 'http://cam/frame.jpeg?src=klipper&t=1');
    } finally {
      vi.useRealTimers();
    }
  });
});

describe('the button', () => {
  it.each([
    ['monitor', 'Launch monitor'],
    ['printer_window', 'Open printer window'],
  ] as const)('%s opens the printer', async (action, label) => {
    const launch = vi.fn();
    card(printer({ action }), launch);
    await userEvent.click(screen.getByRole('button', { name: label }));
    expect(launch).toHaveBeenCalledWith('named:Bench');
  });

  it.each([
    ['reconnect', 'Reconnect'],
    ['connect', 'Connect…'],
  ] as const)('%s asks to connect', async (action, label) => {
    const connect = vi.fn();
    card(printer({ status: 'not_connected', action }), vi.fn(), connect);
    await userEvent.click(screen.getByRole('button', { name: label }));
    expect(connect).toHaveBeenCalledWith('named:Bench');
  });

  it('is left out when there is nothing to do', () => {
    card(printer({ status: 'connecting', action: 'none' }));
    expect(screen.queryByRole('button', { name: /monitor|window|connect/i })).toBeNull();
  });
});

import { useEffect, useState } from 'react';
import type { PrinterCamera, PrinterInfo, PrinterStatus, SpoolInfo } from '../bridge/protocol';
import { printerHistoryLine } from '../history';
import { HistoryGlyph, MonitorGlyph, PrinterGlyph } from './Glyphs';
import { PrinterActions, PrinterMenu } from './PrinterMenu';

// Every card is the same list of fields, top to bottom, and shows each one
// only when the host sent it, so a card grows and shrinks with what its
// printer reports. Only the name and the status are always there. Nothing
// stands in for a field the printer did not report.

const STATUS_WORD: Record<PrinterStatus, string> = {
  not_connected: 'Not connected',
  connecting: 'Connecting…',
  connected: 'Connected',
  ready: 'Ready',
  printing: 'Printing',
  paused: 'Paused',
  attention: 'Needs attention',
};

// "2h 14m left", "14m left".
export function timeLeft(seconds: number): string {
  const minutes = Math.max(1, Math.floor(seconds / 60));
  return minutes >= 60 ? `${Math.floor(minutes / 60)}h ${minutes % 60}m left` : `${minutes}m left`;
}

// What follows the status word: how far a job is, or how the last one ended.
export function statusDetail(printer: PrinterInfo): string | undefined {
  const percent = printer.progressPercent;
  if (printer.status === 'printing') {
    const parts: string[] = [];
    if (percent !== undefined) parts.push(`${Math.round(percent)}%`);
    if (printer.secondsLeft) parts.push(timeLeft(printer.secondsLeft));
    return parts.length > 0 ? parts.join(' · ') : undefined;
  }
  if (printer.status === 'paused') return percent !== undefined ? `at ${Math.round(percent)}%` : undefined;
  if (printer.status === 'ready' && printer.lastPrint) return `last print ${printer.lastPrint}`;
  return undefined;
}

// "Last connected just now", "… 20 min ago", "… 3h ago", "… 2 days ago".
export function lastConnected(iso: string, now: Date = new Date()): string | undefined {
  const at = Date.parse(iso);
  if (Number.isNaN(at)) return undefined;
  const minutes = Math.floor((now.getTime() - at) / 60000);
  if (minutes < 1) return 'Last connected just now';
  if (minutes < 60) return `Last connected ${minutes} min ago`;
  const hours = Math.floor(minutes / 60);
  if (hours < 24) return `Last connected ${hours}h ago`;
  const days = Math.floor(hours / 24);
  return `Last connected ${days} ${days === 1 ? 'day' : 'days'} ago`;
}

// The distinct materials, in the order the spools hold them.
function materials(spools: SpoolInfo[]): string {
  const names: string[] = [];
  for (const spool of spools) {
    if (spool.material && !names.includes(spool.material)) names.push(spool.material);
  }
  return names.join(', ');
}

// How often a camera with only a picture is asked for the next one.
const SNAPSHOT_EVERY_MS = 2000;

// The printer's camera, on the card for as long as it answers: an MJPEG
// stream as it is, a camera with only a picture asked again every couple of
// seconds. One that stops answering is taken off the card rather than left
// as a broken image; the next push of a changed address tries again.
function Camera({ camera, name, status }: { camera: PrinterCamera; name: string; status: PrinterStatus }) {
  const [failed, setFailed] = useState(false);
  const [tick, setTick] = useState(0);
  const stream = camera.streamUrl;
  const snapshot = camera.snapshotUrl;
  useEffect(() => setFailed(false), [stream, snapshot]);
  useEffect(() => {
    if (stream || !snapshot) return undefined;
    const timer = window.setInterval(() => setTick((value) => value + 1), SNAPSHOT_EVERY_MS);
    return () => window.clearInterval(timer);
  }, [stream, snapshot]);
  if (failed) return null;
  const source = stream ?? (snapshot ? `${snapshot}${snapshot.includes('?') ? '&' : '?'}t=${tick}` : undefined);
  if (!source) return null;
  return (
    <div className="printer-camera">
      <img src={source} alt={`Camera view of ${name}`} onError={() => setFailed(true)} />
      <span className="printer-camera-live">
        <span className={`status-dot ${status}`} aria-hidden="true" />
        LIVE
      </span>
    </div>
  );
}

export function PrinterCard({
  printer,
  otherNames,
  actions,
  onLaunchMonitor,
  onHistory,
  highlighted,
  now,
}: {
  printer: PrinterInfo;
  otherNames: string[];
  actions: PrinterActions;
  // Launch monitor, or a print host's Open printer window.
  onLaunchMonitor: (id: string) => void;
  // The Print history filtered to this printer (board history-05).
  onHistory: (id: string) => void;
  // The printer a receipt just named: the card's own CSS animation draws
  // attention to it once and ends on its own -- no timer either side manages.
  highlighted?: boolean;
  now?: Date;
}) {
  // A LAN-only device offers none of the actions; a menu of disabled rows
  // would be a button that does nothing, so it has none.
  const hasActions = printer.canOpenSettings || printer.canRename || printer.canRemove;
  const detail = statusDetail(printer);
  const jobRuns = printer.status === 'printing' || printer.status === 'paused' || printer.status === 'attention';
  const since =
    printer.status === 'not_connected' && printer.lastConnectedAt ? lastConnected(printer.lastConnectedAt, now) : undefined;
  const facts = [printer.connectionLabel, printer.address, printer.modelText].filter(Boolean).join(' · ');
  const loadedText = materials(printer.spools);
  const swatches = printer.spools.filter((spool) => spool.colour);
  const quiet = printer.status === 'not_connected' || printer.status === 'connecting';
  return (
    <div className={highlighted ? 'printer-card printer-card-added' : 'printer-card'}>
      {printer.camera && <Camera camera={printer.camera} name={printer.name} status={printer.status} />}
      <div className="printer-head">
        <span className="printer-name-row">
          <PrinterGlyph />
          <span className="printer-name">{printer.name}</span>
        </span>
        {hasActions && <PrinterMenu printer={printer} otherNames={otherNames} actions={actions} />}
      </div>
      <div className="printer-status">
        {!quiet && <span className={`status-dot ${printer.status}`} aria-hidden="true" />}
        <span className="printer-status-text">
          <span className={quiet ? 'printer-status-word quiet' : 'printer-status-word'}>{STATUS_WORD[printer.status]}</span>
          {detail && <span className="printer-status-detail"> · {detail}</span>}
        </span>
      </div>
      {jobRuns && printer.job && <div className="printer-job">{printer.job}</div>}
      {jobRuns && printer.progressPercent !== undefined && (
        <div
          className={`printer-progress ${printer.status}`}
          role="progressbar"
          aria-label={printer.job ? `${printer.job}, ${Math.round(printer.progressPercent)} percent` : undefined}
          aria-valuenow={Math.round(printer.progressPercent)}
          aria-valuemin={0}
          aria-valuemax={100}
        >
          <span style={{ width: `${Math.max(0, Math.min(100, printer.progressPercent))}%` }} />
        </div>
      )}
      {printer.message && <p className="printer-message">{printer.message}</p>}
      {since && <div className="printer-since">{since}</div>}
      {facts && <div className="printer-facts">{facts}</div>}
      {(loadedText || swatches.length > 0) && (
        <div className="printer-spools">
          {loadedText && <span className="printer-material">{loadedText}</span>}
          {swatches.map((spool, index) => (
            // The border is what keeps a black spool visible on the dark
            // card and a white one on the light card.
            <span key={`${spool.colour}-${index}`} className="spool-swatch" style={{ background: spool.colour }} />
          ))}
        </div>
      )}
      {printer.history && (
        <button type="button" className="project-history printer-history" onClick={() => onHistory(printer.id)}>
          <HistoryGlyph />
          <span className="project-history-text">{printerHistoryLine(printer.history)}</span>
        </button>
      )}
      {(printer.action === 'monitor' || printer.action === 'printer_window') && (
        <button type="button" className="button-secondary launch-monitor" onClick={() => onLaunchMonitor(printer.id)}>
          <MonitorGlyph />
          {printer.action === 'printer_window' ? 'Open printer window' : 'Launch monitor'}
        </button>
      )}
      {(printer.action === 'reconnect' || printer.action === 'connect') && actions.onConnect && (
        <button type="button" className="button-secondary launch-monitor" onClick={() => actions.onConnect?.(printer.id)}>
          {printer.action === 'reconnect' ? 'Reconnect' : 'Connect…'}
        </button>
      )}
    </div>
  );
}

