1	import { useEffect, useState } from 'react';
2	import type { PrinterCamera, PrinterInfo, PrinterStatus, SpoolInfo } from '../bridge/protocol';
3	import { printerHistoryLine } from '../history';
4	import { HistoryGlyph, MonitorGlyph, PrinterGlyph } from './Glyphs';
5	import { PrinterActions, PrinterMenu } from './PrinterMenu';
6	
7	// Every card is the same list of fields, top to bottom, and shows each one
8	// only when the host sent it, so a card grows and shrinks with what its
9	// printer reports. Only the name and the status are always there. Nothing
10	// stands in for a field the printer did not report.
11	
12	const STATUS_WORD: Record<PrinterStatus, string> = {
13	  not_connected: 'Not connected',
14	  connecting: 'Connecting…',
15	  connected: 'Connected',
16	  ready: 'Ready',
17	  printing: 'Printing',
18	  paused: 'Paused',
19	  attention: 'Needs attention',
20	};
21	
22	// "2h 14m left", "14m left".
23	export function timeLeft(seconds: number): string {
24	  const minutes = Math.max(1, Math.floor(seconds / 60));
25	  return minutes >= 60 ? `${Math.floor(minutes / 60)}h ${minutes % 60}m left` : `${minutes}m left`;
26	}
27	
28	// What follows the status word: how far a job is, or how the last one ended.
29	export function statusDetail(printer: PrinterInfo): string | undefined {
30	  const percent = printer.progressPercent;
31	  if (printer.status === 'printing') {
32	    const parts: string[] = [];
33	    if (percent !== undefined) parts.push(`${Math.round(percent)}%`);
34	    if (printer.secondsLeft) parts.push(timeLeft(printer.secondsLeft));
35	    return parts.length > 0 ? parts.join(' · ') : undefined;
36	  }
37	  if (printer.status === 'paused') return percent !== undefined ? `at ${Math.round(percent)}%` : undefined;
38	  if (printer.status === 'ready' && printer.lastPrint) return `last print ${printer.lastPrint}`;
39	  return undefined;
40	}
41	
42	// "Last connected just now", "… 20 min ago", "… 3h ago", "… 2 days ago".
43	export function lastConnected(iso: string, now: Date = new Date()): string | undefined {
44	  const at = Date.parse(iso);
45	  if (Number.isNaN(at)) return undefined;
46	  const minutes = Math.floor((now.getTime() - at) / 60000);
47	  if (minutes < 1) return 'Last connected just now';
48	  if (minutes < 60) return `Last connected ${minutes} min ago`;
49	  const hours = Math.floor(minutes / 60);
50	  if (hours < 24) return `Last connected ${hours}h ago`;
51	  const days = Math.floor(hours / 24);
52	  return `Last connected ${days} ${days === 1 ? 'day' : 'days'} ago`;
53	}
54	
55	// The distinct materials, in the order the spools hold them.
56	function materials(spools: SpoolInfo[]): string {
57	  const names: string[] = [];
58	  for (const spool of spools) {
59	    if (spool.material && !names.includes(spool.material)) names.push(spool.material);
60	  }
61	  return names.join(', ');
62	}
63	
64	// How often a camera with only a picture is asked for the next one.
65	const SNAPSHOT_EVERY_MS = 2000;
66	
67	// The printer's camera, on the card for as long as it answers: an MJPEG
68	// stream as it is, a camera with only a picture asked again every couple of
69	// seconds. One that stops answering is taken off the card rather than left
70	// as a broken image; the next push of a changed address tries again.
71	function Camera({ camera, name, status }: { camera: PrinterCamera; name: string; status: PrinterStatus }) {
72	  const [failed, setFailed] = useState(false);
73	  const [tick, setTick] = useState(0);
74	  const stream = camera.streamUrl;
75	  const snapshot = camera.snapshotUrl;
76	  useEffect(() => setFailed(false), [stream, snapshot]);
77	  useEffect(() => {
78	    if (stream || !snapshot) return undefined;
79	    const timer = window.setInterval(() => setTick((value) => value + 1), SNAPSHOT_EVERY_MS);
80	    return () => window.clearInterval(timer);
81	  }, [stream, snapshot]);
82	  if (failed) return null;
83	  const source = stream ?? (snapshot ? `${snapshot}${snapshot.includes('?') ? '&' : '?'}t=${tick}` : undefined);
84	  if (!source) return null;
85	  return (
86	    <div className="printer-camera">
87	      <img src={source} alt={`Camera view of ${name}`} onError={() => setFailed(true)} />
88	      <span className="printer-camera-live">
89	        <span className={`status-dot ${status}`} aria-hidden="true" />
90	        LIVE
91	      </span>
92	    </div>
93	  );
94	}
95	
96	export function PrinterCard({
97	  printer,
98	  otherNames,
99	  actions,
100	  onLaunchMonitor,
