118	  // would be a button that does nothing, so it has none.
119	  const hasActions = printer.canOpenSettings || printer.canRename || printer.canRemove;
120	  const detail = statusDetail(printer);
121	  const jobRuns = printer.status === 'printing' || printer.status === 'paused' || printer.status === 'attention';
122	  const since =
123	    printer.status === 'not_connected' && printer.lastConnectedAt ? lastConnected(printer.lastConnectedAt, now) : undefined;
124	  const facts = [printer.connectionLabel, printer.address, printer.modelText].filter(Boolean).join(' · ');
125	  const loadedText = materials(printer.spools);
126	  const swatches = printer.spools.filter((spool) => spool.colour);
127	  const quiet = printer.status === 'not_connected' || printer.status === 'connecting';
128	  return (
129	    <div className={highlighted ? 'printer-card printer-card-added' : 'printer-card'}>
130	      {printer.camera && <Camera camera={printer.camera} name={printer.name} status={printer.status} />}
131	      <div className="printer-head">
132	        <span className="printer-name-row">
133	          <PrinterGlyph />
