135	        </span>
136	        {hasActions && <PrinterMenu printer={printer} otherNames={otherNames} actions={actions} />}
137	      </div>
138	      <div className="printer-status">
139	        {!quiet && <span className={`status-dot ${printer.status}`} aria-hidden="true" />}
140	        <span className="printer-status-text">
141	          <span className={quiet ? 'printer-status-word quiet' : 'printer-status-word'}>{STATUS_WORD[printer.status]}</span>
142	          {detail && <span className="printer-status-detail"> · {detail}</span>}
143	        </span>
144	      </div>
145	      {jobRuns && printer.job && <div className="printer-job">{printer.job}</div>}
146	      {jobRuns && printer.progressPercent !== undefined && (
