22	// "2h 14m left", "14m left".
23	export function timeLeft(seconds: number): string {
24	  const minutes = Math.max(1, Math.floor(seconds / 60));
25	  return minutes >= 60 ? `${Math.floor(minutes / 60)}h ${minutes % 60}m left` : `${minutes}m left`;
26	}
