28	// What follows the status word: how far a job is, or how the last one ended.
29	export function statusDetail(printer: PrinterInfo): string | undefined {
30	  const percent = printer.progressPercent;
31	  if (printer.status === 'printing') {
32	    const parts: string[] = [];
33	    if (percent !== undefined) parts.push(`${Math.round(percent)}%`);
34	    if (printer.secondsLeft) parts.push(timeLeft(printer.secondsLeft));
35	    return parts.length > 0 ? parts.join(' · ') : undefined;
36	  }
37	  if (printer.status === 'paused' || printer.status === 'attention')
38	    return percent !== undefined ? `at ${Math.round(percent)}%` : undefined;
39	  if (printer.status === 'ready' && printer.lastPrint) return `last print ${printer.lastPrint}`;
40	  return undefined;
41	}
