43	// "Last connected just now", "… 20 min ago", "… 3h ago", "… 2 days ago".
44	export function lastConnected(iso: string, now: Date = new Date()): string | undefined {
45	  const at = Date.parse(iso);
46	  if (Number.isNaN(at)) return undefined;
47	  const minutes = Math.floor((now.getTime() - at) / 60000);
48	  if (minutes < 1) return 'Last connected just now';
49	  if (minutes < 60) return `Last connected ${minutes} min ago`;
50	  const hours = Math.floor(minutes / 60);
51	  if (hours < 24) return `Last connected ${hours}h ago`;
52	  const days = Math.floor(hours / 24);
53	  return `Last connected ${days} ${days === 1 ? 'day' : 'days'} ago`;
54	}
