66	const SNAPSHOT_EVERY_MS = 2000;
67	// How often the camera is asked, out of sight, whether it still answers.
68	export const CAMERA_CHECK_EVERY_MS = 5000;
69	
70	// A URL asked again rather than served from the cache.
71	function fresh(url: string, tick: number): string {
72	  return `${url}${url.includes('?') ? '&' : '?'}t=${tick}`;
73	}
