75	// The printer's camera, on the card for as long as it answers: an MJPEG
76	// stream as it is, a camera with only a picture asked again every couple of
77	// seconds. A stream that stops raises no error in the app's web view -- the
78	// image keeps its last frame -- so the camera is also asked for one picture
79	// every few seconds, out of sight. One that does not answer is taken off the
80	// card rather than left as a frozen or broken image, and comes back, its
81	// stream reconnected, once it answers again.
82	function Camera({ camera, name, status }: { camera: PrinterCamera; name: string; status: PrinterStatus }) {
83	  const [answering, setAnsweringState] = useState(true);
84	  const answeringNow = useRef(true);
85	  // Bumped when a camera answers again, so the stream connects anew.
86	  const [connection, setConnection] = useState(0);
87	  const setAnswering = (answered: boolean) => {
88	    if (answered && !answeringNow.current) setConnection((value) => value + 1);
89	    answeringNow.current = answered;
90	    setAnsweringState(answered);
91	  };
92	  const [tick, setTick] = useState(0);
93	  const stream = camera.streamUrl;
94	  const snapshot = camera.snapshotUrl;
95	  useEffect(() => {
96	    answeringNow.current = true;
97	    setAnsweringState(true);
98	  }, [stream, snapshot]);
99	  useEffect(() => {
100	    if (stream || !snapshot || !answering) return undefined;
101	    const timer = window.setInterval(() => setTick((value) => value + 1), SNAPSHOT_EVERY_MS);
102	    return () => window.clearInterval(timer);
103	  }, [stream, snapshot, answering]);
104	  useEffect(() => {
105	    const check = snapshot ?? stream;
106	    if (!check) return undefined;
107	    let asked = 0;
108	    let pending: HTMLImageElement | undefined;
109	    const close = (probe: HTMLImageElement) => {
110	      probe.onload = null;
111	      probe.onerror = null;
112	      // Closes a stream asked for as the check.
113	      probe.src = '';
114	    };
115	    const ask = () => {
116	      // A camera still silent since the last check -- a Pi that lost power
117	      // leaves the connection hanging -- is not answering.
118	      if (pending) {
119	        close(pending);
120	        setAnswering(false);
121	      }
122	      const probe = new Image();
123	      pending = probe;
124	      const settle = (answered: boolean) => {
125	        close(probe);
126	        pending = undefined;
127	        setAnswering(answered);
128	      };
129	      probe.onload = () => settle(true);
130	      probe.onerror = () => settle(false);
131	      probe.src = fresh(check, asked++);
132	    };
133	    const timer = window.setInterval(ask, CAMERA_CHECK_EVERY_MS);
134	    return () => {
135	      window.clearInterval(timer);
136	      if (pending) close(pending);
137	    };
138	  }, [stream, snapshot]);
139	  if (!answering) return null;
140	  const source = stream ?? (snapshot ? fresh(snapshot, tick) : undefined);
141	  if (!source) return null;
142	  return (
143	    <div className="printer-camera">
144	      <img key={connection} src={source} alt={`Camera view of ${name}`} onError={() => setAnswering(false)} />
145	      <span className="printer-camera-live">
146	        <span className={`status-dot ${status}`} aria-hidden="true" />
147	        LIVE
148	      </span>
149	    </div>
150	  );
151	}
